import sys
input = sys.stdin.read

def main():
    data = input().split()
    n, l, x, y = map(int, data[:4])
    marks = list(map(int, data[4:]))

    can_measure_x = False
    can_measure_y = False

    marks_set = set(marks)

    for mark in marks:
        if mark + x in marks_set or mark - x in marks_set:
            can_measure_x = True
        if mark + y in marks_set or mark - y in marks_set:
            can_measure_y = True

    if can_measure_x and can_measure_y:
        print(0)
        return

    if can_measure_x:
        print(1)
        for mark in marks:
            if mark + y <= l and (mark + y) not in marks_set:
                print(mark + y)
                return
            if mark - y >= 0 and (mark - y) not in marks_set:
                print(mark - y)
                return

    if can_measure_y:
        print(1)
        for mark in marks:
            if mark + x <= l and (mark + x) not in marks_set:
                print(mark + x)
                return
            if mark - x >= 0 and (mark - x) not in marks_set:
                print(mark - x)
                return

    # If we can't measure either, we try to add one mark to measure both
    for mark in marks:
        if (mark + x <= l and (mark + x) not in marks_set and (
            (mark + x + y in marks_set) or (mark + x - y in marks_set))) or \
           (mark - x >= 0 and (mark - x) not in marks_set and (
            (mark - x + y in marks_set) or (mark - x - y in marks_set))):
            print(1)
            if mark + x <= l and (mark + x) not in marks_set:
                print(mark + x)
            else:
                print(mark - x)
            return

    print(2)
    print(x, y)

main()

